import { expect, expectStatus, test } from "../../fixtures";

test("once a vendor is sent back, its other documents cannot be decided", { tag: "@LIF-03" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor in review, then the reviewer rejects its w9 extraction.
  const { extractions } = await factory.vendorInReview();
  const reviewer = await apiAs("reviewer");
  const rejection = await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
    data: { decision: "reject", note: "Please re-upload the W-9." },
  });
  await expectStatus(rejection, 200);

  // Act: the reviewer approves the contract extraction of the same vendor.
  const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_not_in_review");
});
